<script setup lang="ts">
import { Package, ClipboardList, Banknote, ArrowLeft } from 'lucide-vue-next'
import type { Product, Order } from '../../shared'
import { formatPrice } from '../../shared'
definePageMeta({ layout: 'admin' })
const { data: products } = await useFetch<Product[]>('/api/admin/products', { headers: adminHeaders() })
const { data: orders } = await useFetch<Order[]>('/api/admin/orders', { headers: adminHeaders() })
const paid = computed(() => orders.value?.filter(o => o.payment_status === 'paid') || [])
const revenue = computed(() => paid.value.reduce((sum: number, o: Order) => sum + o.total, 0))
useSeoMeta({ title: 'پیشخوان | مدیریت پیله پاتری', robots: 'noindex' })
</script>
<template><div class="admin-heading"><div><h1 class="admin-title">سلام، به پیله پاتری خوش آمدید 👋</h1><p class="admin-desc">خلاصه‌ای از آنچه در فروشگاهتان می‌گذرد.</p></div></div><div class="stats-grid"><div class="stat-card"><div class="stat-icon"><Package :size="20"/></div><span>محصولات فعال</span><strong>{{ products?.filter(p=>p.active).length || 0 }}</strong><NuxtLink to="/admin/products">مدیریت محصولات <ArrowLeft :size="14"/></NuxtLink></div><div class="stat-card"><div class="stat-icon"><ClipboardList :size="20"/></div><span>سفارش‌های پرداخت‌شده</span><strong>{{ paid.length }}</strong><NuxtLink to="/admin/orders">مشاهده‌ی سفارش‌ها <ArrowLeft :size="14"/></NuxtLink></div><div class="stat-card"><div class="stat-icon"><Banknote :size="20"/></div><span>مجموع پرداخت‌های موفق</span><strong>{{ formatPrice(revenue) }} <small>تومان</small></strong><NuxtLink to="/admin/orders">وضعیت پرداخت‌ها <ArrowLeft :size="14"/></NuxtLink></div></div><div class="dashboard-bottom"><div class="admin-panel"><h2>سفارش‌های اخیر</h2><div v-if="orders?.length"><div v-for="order in orders.slice(0,5)" :key="order.id" class="recent-row"><span>{{ order.customer_name }} <small dir="ltr">{{ order.code }}</small></span><span>{{ formatPrice(order.total) }} تومان</span><span class="pill" :class="order.payment_status==='paid' ? '' : 'warn'">{{ order.payment_status==='paid' ? 'پرداخت موفق' : 'در انتظار / ناموفق' }}</span></div></div><p v-else class="admin-desc">هنوز سفارشی ثبت نشده است.</p></div><div class="admin-panel welcome-panel"><span class="welcome-mark">✳</span><h2>جای خوبی برای شروع است.</h2><p>محصولاتتان را اضافه یا ویرایش کنید، تصاویر واقعی را بارگذاری کنید و فروشگاه را به سبک خودتان بچینید.</p><NuxtLink to="/admin/products" class="admin-primary">رفتن به محصولات <ArrowLeft :size="15"/></NuxtLink></div></div></template>
